	return func(ctx context.Context, b Broadcast, candidates []string) (map[string]struct{}, error) {
		if b.ChannelID == "" && b.TeamID == "" && b.SubjectUserID == "" {
			return nil, nil
		}
		if len(candidates) == 0 {
			return map[string]struct{}{}, nil
