			WITH candidate AS (
				SELECT DISTINCT unnest($4::TEXT[]) AS id
			)
			SELECT recipient.id
			FROM candidate
			JOIN users AS recipient ON recipient.id = candidate.id
			WHERE recipient.delete_at = 0
			  AND (NOT recipient.is_guest OR recipient.guest_expires_at > $5)
			  AND (
				$1 = '' OR EXISTS (
					SELECT 1
