	"github.com/jackc/pgx/v5/pgxpool"
)

func TestPostgresOperationsSnapshotUsesDurableEvidence(t *testing.T) {
	db := newOperationsTestDB(t)
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
	defer cancel()
	if err := store.Migrate(ctx, db); err != nil {
		t.Fatalf("migrate operations schema: %v", err)
	}
	now := time.Now().UnixMilli()
	seedStatements := []string{
		`INSERT INTO users (id, username, email, password_hash, create_at, update_at)
		 VALUES ('ops-user', 'ops-user', 'ops@example.test', 'unused', $1, $1)`,
		`INSERT INTO teams (id, name, display_name, create_at, update_at)
		 VALUES ('ops-team', 'ops-team', 'Operations', $1, $1)`,
		`INSERT INTO channels (id, team_id, type, display_name, name, create_at, update_at)
		 VALUES ('ops-channel', 'ops-team', 'O', 'Operations', 'operations', $1, $1)`,
		`INSERT INTO scheduled_posts
			(id, user_id, channel_id, message, send_at, create_at, sent_at, status, next_attempt_at)
		 VALUES ('ops-scheduled-dead', 'ops-user', 'ops-channel', 'failed', $1, $1, -2, 'dead', 0)`,
		`INSERT INTO file_infos
			(id, user_id, path, name, size, create_at, update_at)
		 VALUES ('ops-file', 'ops-user', 'opaque/path', 'status.txt', 1536, $1, $1)`,
		`INSERT INTO integration_deliveries
			(id, event_id, integration_id, callback_url, payload, status, next_attempt_at, create_at, update_at)
		 VALUES
			('ops-retry', 'event-retry', 'hook-1', 'https://example.test/retry', '{}'::jsonb, 'retry', $1, $1, $1),
			('ops-dead', 'event-dead', 'hook-1', 'https://example.test/dead', '{}'::jsonb, 'dead', 0, $1, $1)`,
	}
	for _, statement := range seedStatements {
		if _, err := db.Pool.Exec(ctx, statement, now); err != nil {
			t.Fatalf("seed operations state: %v", err)
		}
	}

	reader := newPostgresOperationsReader(db, fileStorageRuntime{
		ConfiguredBackend: "fs",
		ActiveBackend:     "fs",
		FilesystemRoot:    t.TempDir(),
	})
	snapshot := reader.Snapshot(ctx)

	if snapshot.Database.State != operationalReady || snapshot.Database.Migration.AppliedVersion != snapshot.Database.Migration.TargetVersion {
		t.Fatalf("database status = %#v", snapshot.Database)
	}
	if snapshot.Workers.State != operationalWarning || snapshot.Workers.Scheduled.Dead != 1 || snapshot.Workers.RuntimeObservable {
		t.Fatalf("worker status = %#v", snapshot.Workers)
	}
	if snapshot.Webhooks.State != operationalWarning || snapshot.Webhooks.Retry != 1 || snapshot.Webhooks.Dead != 1 || snapshot.Webhooks.RuntimeObservable {
		t.Fatalf("webhook status = %#v", snapshot.Webhooks)
	}
	if snapshot.Storage.State != operationalReady || snapshot.Storage.FileCount != 1 || snapshot.Storage.Bytes != 1536 {
		t.Fatalf("storage status = %#v", snapshot.Storage)
	}
}

func TestStorageFallbackIsWarningEvenWhenFilesystemExists(t *testing.T) {
	db := newOperationsTestDB(t)
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
	defer cancel()
	if err := store.Migrate(ctx, db); err != nil {
		t.Fatal(err)
	}
	reader := newPostgresOperationsReader(db, fileStorageRuntime{
		ConfiguredBackend: "s3", ActiveBackend: "fs", Fallback: true, FilesystemRoot: t.TempDir(),
	})
	storageStatus := reader.Snapshot(ctx).Storage
	if storageStatus.State != operationalWarning || !storageStatus.Fallback || storageStatus.ActiveBackend != "fs" {
		t.Fatalf("fallback status = %#v", storageStatus)
	}
}

func newOperationsTestDB(t *testing.T) *store.DB {
	t.Helper()
	dsn := strings.TrimSpace(os.Getenv("MOYRO_TEST_POSTGRES_DSN"))
	if dsn == "" {
		t.Skip("MOYRO_TEST_POSTGRES_DSN is not set")
	}
	ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
	defer cancel()
	adminPool, err := pgxpool.New(ctx, dsn)
	if err != nil {
		t.Fatal(err)
	}
	if err := adminPool.Ping(ctx); err != nil {
		adminPool.Close()
		t.Fatal(err)
	}
	schemaName := "moyro_operations_" + strings.ReplaceAll(uuid.NewString(), "-", "")
	quotedSchema := pgx.Identifier{schemaName}.Sanitize()
	if _, err := adminPool.Exec(ctx, "CREATE SCHEMA "+quotedSchema); err != nil {
		adminPool.Close()
		t.Fatal(err)
	}
	config, err := pgxpool.ParseConfig(dsn)
	if err != nil {
		adminPool.Close()
		t.Fatal(err)
	}
	config.ConnConfig.RuntimeParams["search_path"] = quotedSchema
	config.MaxConns = 4
	testPool, err := pgxpool.NewWithConfig(ctx, config)
	if err != nil {
		adminPool.Close()
		t.Fatal(err)
	}
	t.Cleanup(func() {
		testPool.Close()
		cleanupCtx, cleanupCancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer cleanupCancel()
		if _, err := adminPool.Exec(cleanupCtx, "DROP SCHEMA "+quotedSchema+" CASCADE"); err != nil {
			t.Errorf("drop operations schema: %v", err)
		}
		adminPool.Close()
	})
	return &store.DB{Pool: testPool}
}
package userstatus

import (
	"context"
	"encoding/json"
	"time"

	"github.com/hkjang/moyro/server/internal/store"
	"github.com/jackc/pgx/v5"
)

// Valid status values. Mattermost-compatible.
const (
	Online  = "online"
	Away    = "away"
	DND     = "dnd"
	Offline = "offline"
)

type Status struct {
	UserID         string `json:"user_id"`
	Status         string `json:"status"`
	Manual         bool   `json:"manual"`
	LastActivityAt int64  `json:"last_activity_at"`
}

type Service struct{ db *store.DB }

func New(db *store.DB) *Service { return &Service{db: db} }

// Get returns the current status for a user, synthesising an offline
// default if the user has never checked in.
func (s *Service) Get(ctx context.Context, userID string) (*Status, error) {
	var st Status
	err := s.db.Pool.QueryRow(ctx, `
		SELECT user_id, status, manual, last_activity_at FROM user_statuses WHERE user_id=$1
	`, userID).Scan(&st.UserID, &st.Status, &st.Manual, &st.LastActivityAt)
	if err != nil {
		// Synthesise an offline status rather than 404 — matches Mattermost.
		return &Status{UserID: userID, Status: Offline}, nil
	}
	return &st, nil
}

// GetMany fetches status for a list of user IDs in one round-trip.
func (s *Service) GetMany(ctx context.Context, userIDs []string) ([]Status, error) {
	out := make([]Status, 0, len(userIDs))
	if len(userIDs) == 0 {
		return out, nil
	}
	rows, err := s.db.Pool.Query(ctx, `
		SELECT user_id, status, manual, last_activity_at FROM user_statuses WHERE user_id = ANY($1::text[])
	`, userIDs)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	byUserID := make(map[string]Status, len(userIDs))
	for rows.Next() {
		var st Status
		if err := rows.Scan(&st.UserID, &st.Status, &st.Manual, &st.LastActivityAt); err != nil {
			return nil, err
		}
		byUserID[st.UserID] = st
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	// Preserve the caller's input order while padding unseen users with
	// offline, so permission-filtered bulk hydration remains deterministic.
	for _, uid := range userIDs {
		if st, ok := byUserID[uid]; ok {
			out = append(out, st)
		} else {
			out = append(out, Status{UserID: uid, Status: Offline})
		}
	}
	return out, nil
}

// Set upserts a status row. manual=true means the user explicitly picked
// this state (e.g. DND) and auto-presence should not override it.
func (s *Service) Set(ctx context.Context, userID, status string, manual bool) (*Status, error) {
	now := time.Now().UnixMilli()
	_, err := s.db.Pool.Exec(ctx, `
		INSERT INTO user_statuses (user_id, status, manual, last_activity_at, update_at)
		VALUES ($1,$2,$3,$4,$4)
		ON CONFLICT (user_id) DO UPDATE SET
			status = EXCLUDED.status,
			manual = EXCLUDED.manual,
			last_activity_at = EXCLUDED.last_activity_at,
			update_at = EXCLUDED.update_at
	`, userID, status, manual, now)
	if err != nil {
		return nil, err
	}
	return &Status{UserID: userID, Status: status, Manual: manual, LastActivityAt: now}, nil
}

// CustomStatus mirrors Mattermost's `{emoji, text, duration?, expires_at?}`
// payload. We store it as a JSONB blob on user_statuses.custom_status so the
// shape stays open-ended (Mattermost sometimes adds fields with point releases)
// without a migration per addition.
type CustomStatus struct {
	Emoji     string `json:"emoji"`
	Text      string `json:"text"`
	Duration  string `json:"duration,omitempty"`
	ExpiresAt string `json:"expires_at,omitempty"`
}

// GetCustomStatus returns the user's custom status, or nil if unset / empty.
// Mattermost's contract is that an absent custom status returns 404, but the
// official client tolerates a 200 + empty object — we return the empty form so
// callers don't need a special-case.
func (s *Service) GetCustomStatus(ctx context.Context, userID string) (*CustomStatus, error) {
	var raw []byte
	err := s.db.Pool.QueryRow(ctx, `SELECT custom_status FROM user_statuses WHERE user_id=$1`, userID).Scan(&raw)
	if err == pgx.ErrNoRows {
		return &CustomStatus{}, nil
	}
	if err != nil {
		return nil, err
	}
	if len(raw) == 0 || string(raw) == "{}" {
		return &CustomStatus{}, nil
	}
	var cs CustomStatus
	if err := json.Unmarshal(raw, &cs); err != nil {
		return &CustomStatus{}, nil
	}
	return &cs, nil
}

// SetCustomStatus stamps the JSONB column. We auto-create the user_statuses
// row if it doesn't exist yet so a brand-new account that hasn't touched the
// presence WS yet can still set a custom status.
func (s *Service) SetCustomStatus(ctx context.Context, userID string, cs CustomStatus) error {
	raw, err := json.Marshal(cs)
	if err != nil {
		return err
	}
	now := time.Now().UnixMilli()
	_, err = s.db.Pool.Exec(ctx, `
		INSERT INTO user_statuses (user_id, status, manual, last_activity_at, update_at, custom_status)
		VALUES ($1, 'online', false, $2, $2, $3)
		ON CONFLICT (user_id) DO UPDATE SET
			custom_status = EXCLUDED.custom_status,
			update_at     = EXCLUDED.update_at
	`, userID, now, raw)
	return err
}

// ClearCustomStatus zeroes the JSONB blob (without touching presence/manual).
func (s *Service) ClearCustomStatus(ctx context.Context, userID string) error {
	_, err := s.db.Pool.Exec(ctx, `UPDATE user_statuses SET custom_status='{}'::jsonb, update_at=$2 WHERE user_id=$1`, userID, time.Now().UnixMilli())
	return err
}

// SetAuto writes a status only when the user has not explicitly pinned a
// state (i.e. existing row has manual=false, or no row exists yet). Used
// by the WS hub on connect/disconnect so DND/away choices stick across
// reconnects.
func (s *Service) SetAuto(ctx context.Context, userID, status string) (*Status, error) {
