  local absolute_path="${repo_root}/${relative_path}"

  if [[ ! -f "${absolute_path}" ]]; then
    echo "source-size: missing tracked file: ${relative_path}" >&2
    failed=1
    return
  fi

  local actual_bytes
  actual_bytes="$(wc -c < "${absolute_path}")"
  if (( actual_bytes > max_bytes )); then
