+	socket, response, err := dialer.DialContext(f.ctx,
+		"ws"+strings.TrimPrefix(f.server.URL, "http")+"/api/v4/websocket", header)
+	if response != nil && response.Body != nil {
+		_ = response.Body.Close()
+	}
+	if err != nil {
